// 함정 1: 고정 크기
List<String> fixed = Arrays.asList("a", "b", "c");
fixed.set(0, "x");  // OK (요소 교체)
// fixed.add("d");   // UnsupportedOperationException!
// fixed.remove(0);  // UnsupportedOperationException!

// 함정 2: 원본 배열과 연결
String[] arr = {"a", "b", "c"};
List<String> linked = Arrays.asList(arr);
arr[0] = "x";
System.out.println(linked.get(0));  // "x"!

// 해결책: 새 ArrayList 생성
List<String> mutable = new ArrayList<>(Arrays.asList("a", "b", "c"));
mutable.add("d");  // OK!

// Java 9+: List.of() (완전 불변)
List<String> immutable = List.of("a", "b", "c");
// immutable.set(0, "x");  // UnsupportedOperationException!
